using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;
public static class VerifyFramingEF
{
 const string D="Assets/M/CodexTemp/ElevatorCinematicFraming_20261030~/";static ElevatorLesson l;static ElevatorPlayerMovement m;static ElevatorDesktopControls c;static ElevatorSportsCentreMap map;static List<object> checks;static string mode;
 static void Check(bool ok,string name){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);}
 static void Warp(Vector3 p){m.Controller.enabled=false;m.transform.position=p;m.Controller.enabled=true;m.CalibrateFeet(p.y);m.ResetVerticalMotion();Physics.SyncTransforms();}
 static void Fits(RectTransform rect,string label,float bottom=.035f,float top=.965f){var corners=new Vector3[4];rect.GetWorldCorners(corners);var points=corners.Select(l.playerCamera.WorldToViewportPoint).ToArray();Check(points.All(p=>p.z>l.playerCamera.nearClipPlane&&p.x>.025f&&p.x<.975f&&p.y>bottom&&p.y<top),label+" fits viewport: "+string.Join(";",points.Select(p=>p.ToString("F3"))));}
 static void Speech(string label,bool bars=false){Check(l.view.dialoguePanel.gameObject.activeInHierarchy&&l.view.GetComponent<CanvasGroup>().alpha>.99f,label+": dialogue is visible");Check(l.view.dialogueText.maxVisibleCharacters>0,label+": dialogue text is revealed");Fits(l.view.dialoguePanel,label+": speech",bars?.13f:.035f,bars?.87f:.965f);if(l.view.spatial)Fits(l.view.spatial.speakerTab,label+": speaker tab",bars?.13f:.035f,bars?.87f:.965f);foreach(var b in l.view.ChoiceButtons.Where(b=>b&&b.IsActive()))Fits((RectTransform)b.transform,label+": "+b.name,bars?.13f:.035f,bars?.87f:.965f);}
 static async Task Shot(string name){await Awaitable.EndOfFrameAsync();ScreenCapture.CaptureScreenshot(D+mode+"_"+name+".png");await Task.Delay(80);}
 static async Task Mouse(bool down){var s=new MouseState{position=new Vector2(Screen.width*.5f,Screen.height*.5f)};if(down)s=s.WithButton(MouseButton.Left,true);InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,s);await Task.Delay(95);}
 static async Task Next(){var b=l.view.ChoiceButtons.Single();var r=Quaternion.LookRotation(b.transform.position-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse(false);Check(c.HoverTargetName=="DialogueNext","Next button can be reached by the real pointer");await Mouse(true);await Mouse(false);}
 public static async Task<string> Main()
 {
  UnityEditor.EditorApplication.ExecuteMenuItem("Window/General/Game");l=Object.FindFirstObjectByType<ElevatorLesson>();m=Object.FindFirstObjectByType<ElevatorPlayerMovement>();c=Object.FindFirstObjectByType<ElevatorDesktopControls>();map=l.presentation.space.sportsCentre;mode=l.scenario.objectGuidedScene?"Guided":"Original";checks=new List<object>();string error=null;float aspect=l.playerCamera.aspect;
  var old=InputSystem.settings;var temp=Object.Instantiate(old);temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;var hardware=UnityEngine.InputSystem.Mouse.current;bool wasEnabled=hardware!=null&&hardware.enabled;if(wasEnabled)InputSystem.DisableDevice(hardware);var mouse=InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>("InteriorFramingQA");mouse.MakeCurrent();
  try{
   l.DeveloperJump(2);l.presentation.space.overlay.Advance(2);await Task.Delay(850);Warp(new Vector3(-1.85f,7.92f,4.4f));c.SetLookAngles(70,40);var start=m.FeetPosition;l.UnsafeProposal();await Task.Delay(170);Check(map.IsFraming&&l.CinematicBlocking&&!m.CanMove,"Input is blocked during cabin reposition");Check(Vector3.Distance(m.FeetPosition,start)>.01f&&Vector3.Distance(m.FeetPosition,map.inside)>.01f,"PC reposition is a short movement, not an instant cut");await Task.Delay(650);Check(Vector3.Distance(m.FeetPosition,map.inside)<.025f,"Shot ends at the authored cabin position");Check(!map.IsFraming,"Reposition finishes");Speech("Jump cinematic",true);var actor=l.playerCamera.WorldToViewportPoint(l.friend.position+Vector3.up);Check(actor.z>0&&actor.x>.03f&&actor.x<.97f&&actor.y>.13f&&actor.y<.87f,"Friend and speech are in the same shot");await Shot("01_Jump");
   l.DeveloperJump(2);await Task.Delay(850);Warp(new Vector3(-2.7f,7.92f,5.4f));var free=m.FeetPosition;await Task.Delay(220);Check(Vector2.Distance(new Vector2(free.x,free.z),new Vector2(m.FeetPosition.x,m.FeetPosition.z))<.025f&&m.CanMove,"Exploration is released after placement and does not snap back");m.Move(Vector2.up,.08f,false);Check(Vector3.Distance(free,m.FeetPosition)>.03f,"Walking still works between story beats");
   l.DeveloperJump(4);await Task.Delay(850);Speech("Operator dialogue");l.ReportSituation();await Task.Delay(1200);Warp(new Vector3(-.7f,7.92f,3.95f));c.SetLookAngles(90,45);l.FindIdentity();Check(map.IsFraming&&l.Flow.Elapsed>1,"Reading the ID starts a fresh reposition within the same dialogue step");await Task.Delay(850);Check(Vector2.Distance(new Vector2(m.FeetPosition.x,m.FeetPosition.z),new Vector2(map.inside.x,map.inside.z))<.025f&&Mathf.Abs(m.FeetPosition.y-map.inside.y)<.12f,"Identity report returns to the conversation viewpoint");Speech("Identity report");await Shot("02_Identity");await Next();Check(l.Flow.LocationReported,"Next reports the location after the camera correction");await Next();Check(l.Flow.Step==ElevatorStep.Waiting,"Next still reaches the waiting stage");await Task.Delay(850);Speech("Waiting");await Shot("03_Waiting");
   l.playerCamera.aspect=4f/3;l.DeveloperJump(2);await Task.Delay(850);Speech("4:3 proposal");await Shot("04_Aspect4by3");l.playerCamera.aspect=aspect;
   l.DeveloperJump(3);await Task.Delay(130);var paused=m.FeetPosition;float elapsed=l.Flow.Elapsed;l.pauseMenu.Toggle();await Task.Delay(250);Check(l.IsPaused&&Vector3.Distance(paused,m.FeetPosition)<.001f&&Mathf.Abs(l.Flow.Elapsed-elapsed)<.001f,"Pause freezes reposition and its story clock");l.pauseMenu.Toggle();await Task.Delay(850);Check(!l.IsPaused&&!map.IsFraming,"Resume completes the same reposition");
   l.DeveloperJump(5);await Task.Delay(850);l.Reassure();l.Advance(5.2f);await Task.Delay(850);Check(l.Flow.Step==ElevatorStep.Rescue,"Waiting fade still leads to rescue");Speech("Rescue cinematic",true);await Shot("05_Rescue");
   l.Restart();l.presentation.space.overlay.Advance(2);
  }catch(Exception e){error=e.ToString();await Shot("Failure");}
  finally{if(l.IsPaused)l.pauseMenu.Toggle();l.playerCamera.aspect=aspect;InputSystem.RemoveDevice(mouse);if(wasEnabled)InputSystem.EnableDevice(hardware);hardware?.MakeCurrent();InputSystem.settings=old;Object.Destroy(temp);}
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,mode,passed=checks.Count(o=>(bool)o.GetType().GetProperty("passed").GetValue(o)),checks,error},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+mode+"Verification.json",report);return report;
 }
}